package com.college.hospitalmanagement;
import jakarta.persistence.*;
@Entity @Table(name="wards") public class Ward{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,unique=true,length=150) private String name;@Column(nullable=false,unique=true,length=30) private String code;@Column(nullable=false) private Integer floor;@Column(nullable=false,length=50) private String wardType;@Column(length=1000) private String description;@Column(nullable=false,length=20) private String status;public Long getId(){return id;}public String getName(){return name;}public String getCode(){return code;}public Integer getFloor(){return floor;}public String getWardType(){return wardType;}public String getDescription(){return description;}public String getStatus(){return status;}public void setName(String v){name=v;}public void setCode(String v){code=v;}public void setFloor(Integer v){floor=v;}public void setWardType(String v){wardType=v;}public void setDescription(String v){description=v;}public void setStatus(String v){status=v;}}
